-- 0023_locations.sql
-- GENERATED by scripts/gen-locations-db.mjs from data/locations.js. Do not
-- edit by hand; rebuild data/locations.js (scripts/build-locations.mjs) and
-- regenerate.
--
-- Jordan's places, three levels deep: the 12 governorates, then
-- 1182 cities, towns and villages, then 452 neighbourhoods. Place names
-- beyond the original hand-checked ones are from GeoNames (geonames.org),
-- CC BY 4.0.
--
--   1. governorates: new, readable by everyone.
--   2. cities gain their governorate, the spellings people type, an on/off
--      switch, and `edited`; neighborhoods gain the switch and `edited`.
--   3. Every place upserted. A row an admin has changed in the admin panel
--      (edited = true) is left as the admin left it, and a place an admin
--      added is never touched.
--
-- ADDITIVE ONLY, and safe to run more than once. No listing is touched:
-- every city and neighbourhood id that existed before keeps its row, so
-- every listing still points at the same place.

/* ── 1. Governorates ──────────────────────────────────────────────────── */

create table if not exists public.governorates (
  id          text primary key check (id ~ '^[a-z0-9][a-z0-9-]{1,40}$'),
  name_en     text not null check (char_length(name_en) between 1 and 80),
  name_ar     text not null check (char_length(name_ar) between 1 and 80),
  lat         double precision,
  lng         double precision,
  aliases     text[] not null default '{}',
  sort        integer not null default 100,
  active      boolean not null default true,
  edited      boolean not null default false,
  updated_at  timestamptz not null default now()
);

alter table public.governorates enable row level security;
drop policy if exists "governorates readable by anyone" on public.governorates;
create policy "governorates readable by anyone" on public.governorates for select using (true);
revoke all on public.governorates from anon, authenticated, public;
grant select on public.governorates to anon, authenticated;
grant all on public.governorates to service_role;

/* ── 2. New columns ───────────────────────────────────────────────────── */

alter table public.cities add column if not exists governorate_id text references public.governorates (id) on update cascade;
alter table public.cities add column if not exists aliases     text[] not null default '{}';
alter table public.cities add column if not exists active      boolean not null default true;
alter table public.cities add column if not exists edited      boolean not null default false;
alter table public.cities add column if not exists geonames_id integer;
alter table public.cities add column if not exists updated_at  timestamptz not null default now();

alter table public.neighborhoods add column if not exists active      boolean not null default true;
alter table public.neighborhoods add column if not exists edited      boolean not null default false;
alter table public.neighborhoods add column if not exists geonames_id integer;
alter table public.neighborhoods add column if not exists updated_at  timestamptz not null default now();

create index if not exists cities_governorate_idx on public.cities (governorate_id);
create index if not exists neighborhoods_city_idx on public.neighborhoods (city_id);
-- What the website and the app fetch to pick up an admin's changes.
create index if not exists cities_edited_idx on public.cities (edited) where edited;
create index if not exists neighborhoods_edited_idx on public.neighborhoods (edited) where edited;

/* ── 3. The places ────────────────────────────────────────────────────── */

on conflict (id) do update
  set name_en = excluded.name_en, name_ar = excluded.name_ar, lat = excluded.lat, lng = excluded.lng,
      aliases = excluded.aliases, sort = excluded.sort, updated_at = now()
  where not public.governorates.edited;

on conflict (id) do update
  set governorate_id = excluded.governorate_id, name_en = excluded.name_en, name_ar = excluded.name_ar,
      lat = excluded.lat, lng = excluded.lng, aliases = excluded.aliases, geonames_id = excluded.geonames_id,
      updated_at = now()
  where not public.cities.edited;

on conflict (id) do update
  set city_id = excluded.city_id, name_en = excluded.name_en, name_ar = excluded.name_ar,
      lat = excluded.lat, lng = excluded.lng, aliases = excluded.aliases, geonames_id = excluded.geonames_id,
      updated_at = now()
  where not public.neighborhoods.edited;

notify pgrst, 'reload schema';
